#define main anneal_main
#include "lp2_p15_arbitrary16_prime_anneal.cpp"
#undef main
#include <iomanip>
struct Candidate{int o;Perm p;double approx;float score;};
array<double,29> unigram(){array<double,29> f{};f.fill(.5);ifstream in("prior.txt");string s;while(in>>s)for(char c:s)f[c<='9'?c-'0':c-'a'+10]++;double n=accumulate(f.begin(),f.end(),0.0);for(double& x:f)x/=n;return f;}
// Maximum weighted assignment via the standard primal-dual Hungarian method.
pair<Perm,double> assign(double a[16][16]){double u[17]={},v[17]={};int p[17]={},way[17]={};for(int i=1;i<=16;i++){p[0]=i;int j0=0;double minv[17];fill(minv,minv+17,1e100);bool used[17]={};do{used[j0]=true;int i0=p[j0],j1=0;double d=1e100;for(int j=1;j<=16;j++)if(!used[j]){double cur=-a[i0-1][j-1]-u[i0]-v[j];if(cur<minv[j]){minv[j]=cur;way[j]=j0;}if(minv[j]<d){d=minv[j];j1=j;}}for(int j=0;j<=16;j++)if(used[j]){u[p[j]]+=d;v[j]-=d;}else minv[j]-=d;j0=j1;}while(p[j0]);do{int j1=way[j0];p[j0]=p[j1];j0=j1;}while(j0);}Perm q;double s=0;for(int j=1;j<=16;j++){q[p[j]-1]=j-1;s+=a[p[j]-1][j-1];}return {q,s};}
vector<Candidate> rank_origins(const vector<int>& c,int N,double holdProb){auto f=unigram();vector<vector<double>> pri(N);int z=0;for(int i=0;i<N;i+=16){int zz=count(c.begin()+i,c.begin()+i+16,0);for(int s=0;s<16;s++){int m=z+(zz*s+8)/16;m=min(m,i+s);auto& w=pri[i+s];w.assign(m+1,0);w[0]=1;for(int x=0;x<m;x++)for(int h=x+1;h>=0;h--)w[h]=(h<=x?w[h]*(1-holdProb):0)+(h?w[h-1]*holdProb:0);}z+=zz;}
vector<Candidate> v;for(int o=0;o<=3301;o++){double a[16][16]={};for(int i=0;i<N;i++){int s=i%16,b=i-s;double fsum[29]={};for(int h=0;h<pri[i].size();h++){int k=K[o+i-h];double w=pri[i][h];for(int j=1;j<29;j++)fsum[(j+k)%29]+=w*f[j];}fsum[0]+=f[0];for(int j=0;j<16;j++)a[s][j]+=log(max(1e-15,fsum[c[b+j]]));}auto [p,s]=assign(a);v.push_back({o,p,s,score(c,p,o,928,12).score});}sort(v.begin(),v.end(),[](const Candidate&a,const Candidate&b){return a.score>b.score;});return v;}
int main(int argc,char**argv){train();string mode=argv[1];int trueOrigin=stoi(argv[2]),n=stoi(argv[3]);double holdProb=stod(argv[4]);int top=stoi(argv[5]),iters=stoi(argv[6]);auto raw=read("raw.txt"),donor=read("donor.txt");Perm truth{5,10,12,14,6,0,15,11,2,7,1,8,3,4,13,9};auto c=mode=="plant"?reorder(enc(donor,trueOrigin),inv(truth)):raw;auto ranked=rank_origins(c,n,holdProb);if(mode=="plant"){auto t=find_if(ranked.begin(),ranked.end(),[&](auto x){return x.o==trueOrigin;});cout<<"true origin rank "<<1+(t-ranked.begin())<<" score "<<t->score/928<<" approx "<<t->approx/n<<" true perm score "<<score(c,truth,trueOrigin,928,12).score/928<<endl;}mt19937 rng(3301);uniform_real_distribution<float> u(0,1);Candidate best{};best.score=NEG;for(int rank=0;rank<top;rank++){auto x=ranked[rank];Perm p=x.p;float s=x.score;for(int j=0;j<iters;j++){Perm q=p;swap(q[rng()%16],q[rng()%16]);float t=score(c,q,x.o,928,12).score;float T=8*pow(.035f,float(j)/iters);if(t>s||u(rng)<exp((t-s)/T)){p=q;s=t;}if(s>best.score)best={x.o,p,x.approx,s};}if(rank<5||rank%10==9)cout<<"rank "<<rank+1<<" origin "<<x.o<<" best "<<best.o<<" "<<best.score/928<<endl;}
cout<<"selected origin "<<best.o<<" score "<<best.score/928<<" perm ";printp(best.p);cout<<endl;auto tr=score(c,best.p,best.o,928,1e6,true),full=score(c,best.p,best.o,c.size(),1e6,true);cout<<"strict train score "<<tr.score/928<<" errors "<<tr.errors<<" full score "<<full.score/c.size()<<" errors "<<full.errors<<endl;if(mode=="plant"){int k=0,correct=0,hold=0;for(int i=0;i<16;i++)k+=best.p[i]==truth[i];for(int i=0;i<full.plain.size();i++){correct+=full.plain[i]==donor[i];if(i>=928)hold+=full.plain[i]==donor[i];}cout<<"key "<<k<<"/16 full correct "<<correct<<" withheld "<<hold<<endl;}if(!full.errors)assert(reorder(enc(full.plain,best.o),inv(best.p))==c);return 0;}
